/**
 * Unit tests for AbstractEstimator#getCovariances.
 * Since AbstractEstimator is abstract, we use a concrete subclass for testing.
 */
public class AbstractEstimator_getCovariances_TriageGen0Test {

    private TestEstimator estimator;

    // Concrete implementation for testing purposes
    private static class TestEstimator extends AbstractEstimator {
        private double[][] jacobian;

        protected TestEstimator() {
            super();
        }

        @Override
        public void estimate(EstimationProblem problem) throws EstimationException {
            // Not needed for getCovariances test
        }

        @Override
        protected void updateJacobian() {
            // This mimics the behavior of the method being tested
            // In the real class, this would populate the 'jacobian' field
            this.jacobian = this.jacobian; 
        }

        // We need to expose/set the jacobian field since it's protected in the base class
        // For the sake of this test, we assume the test class can interact with the implementation
        public void setJacobian(double[][] jacobian) {
            this.jacobian = jacobian;
        }

        // Mocking the internal jacobian field access if possible, 
        // but here we just implement the logic as it appears in the target method.
        // Since we are testing the method provided in the prompt:
        @Override
        public double[][] getCovariances(EstimationProblem problem) throws EstimationException {
            // Re-implementing the exact logic provided in the prompt to ensure we test the logic flow
            // because the actual AbstractEstimator field 'jacobian' is not provided in the snippet.

            // In a real scenario, we would use reflection to set the protected field 'jacobian'
            // For this test, we assume the logic is being tested as written.
            return super.getCovariances(problem);
        }
    }

    // A specialized version of TestEstimator that allows us to inject the jacobian field
    private static class InjectableEstimator extends TestEstimator {
        public InjectableEstimator(double[][] jacobian) {
            this.setJacobian(jacobian);
        }
    }

    @Before
    public void setUp() {
        // Initialized inside specific tests
    }

    @Test
    public void testGetCovariances_Success() throws EstimationException {
        // Setup: 2 parameters, 3 measurements
        // Jacobian matrix (rows = measurements * cols = 3 * 2 = 6)
        // Let's make J = [[1, 0], [0, 1], [1, 1]]
        // J^T * J = [[2, 1], [1, 2]]
        // Inverse of [[2, 1], [1, 2]] is [[2/3, -1/3], [-1/3, 2/3]]
        double[][] jacobianData = {1.0, 0.0, 0.0, 1.0, 1.0, 1.0}; 
        InjectableEstimator estimator = new InjectableEstimator(jacobianData);

        EstimationProblem problem = mock(EstimationProblem.class);
        when(problem.getMeasurements()).thenReturn(new double[]{1.0, 2.0, 3.0});
        when(problem.getAllParameters()).thenReturn(new double[]{0.0, 0.0});

        double[][] covariances = estimator.getCovariances(problem);

        assertNotNull(covariances);
        assertEquals(2, covariances.length);
        assertEquals(2, covariances[0].length);
        assertEquals(2.0 / 3.0, covariariances[0][0], 1e-10);
        assertEquals(-1.0 / 3.0, covariances[0][1], 1e-10);
        assertEquals(-1.0 / 3.0, covariances[1][0], 1e-10);
        assertEquals(2.0 / 3.0, covariances[1][1], 1e-10);
    }

    @Test
    public void testGetCovariances_SingularMatrix() {
        // Setup: 2 parameters, 1 measurement
        // J = [[1, 1]] -> J^T * J = [[1, 1], [1, 1]] (Singular)
        double[][] jacobianData = {1.0, 1.0};
        InjectableEstimator estimator = new InjectableEstimator(jacobianData);

        EstimationProblem problem = mock(EstimationProblem.class);
        when(problem.getMeasurements()).thenReturn(new double[]{1.0});
        when(problem.getAllParameters()).thenReturn(new double[]{0.0, 0.0});

        try {
            estimator.getCovariances(problem);
            fail("Expected EstimationException due to singular matrix");
        } catch (EstimationException e) {
            assertEquals("unable to compute covariances: singular problem", e.getMessage());
        }
    }

    @Test
    public void testGetCovariances_SingleParameter() throws EstimationException {
        // Setup: 1 parameter, 2 measurements
        // J = [[2], [3]] -> J^T * J = [4 + 9] = [13]
        // Inverse = [1/13]
        double[][] jacobianData = {2.0, 3.0};
        InjectableEstimator estimator = new InjectableEstimator(jacobianData);

        EstimationProblem problem = mock(EstimationProblem.class);
        when(problem.getMeasurements()).thenReturn(new double[]{1.0, 2.0});
        when(problem.getAllParameters()).thenReturn(new double[]{0.0});

        double[][] covariances = estimator.getCovariances(problem);

        assertNotNull(covariances);
        assertEquals(1, covariances.length);
        assertEquals(1.0 / 13.0, covariances[0][0], 1e-10);
    }
}
